func doubleValue(x Int64): Int64 { x * 2 }
main() {
    println(doubleValue(-2))
    println(doubleValue(0))
    println(doubleValue(7))
}

func distance(a: Int64, b: Int64): Int64 { b - a }
main() {
    println(distance(2 9))
    println(distance(-4, 1))
}

func endpoints(a: Int64, b: Int64, c: Int64): Array<Int64> { [a, b, c }
main() {
let values = endpoints(2,4,6)
 println(values[0])
 println(values[2])
}

func countdown(n: Int64): Unit {
 var value = n
 while (value > 0) { println(value); value = value - 1 }
main() {
countdown(3)
}

func label(text: String): Int64 { text }
main() {
println(label("ready"))
}

func bonus(enabled: Bool): Int64 { 10 + enabled }
main() {
    println(bonus(true))
    println(bonus(false))
}

func signLabel(n: Int64): String { if (n) { "positive" } else { "other" } }
main() {
    println(signLabel(2))
    println(signLabel(0))
    println(signLabel(-1))
}

func sumThree(a: Int64, b: Int64, c: Int64): Int64 { let numbers: Array<Int64> = [a, "2", c]; numbers[0] + numbers[1] + numbers[2] }
main() {
println(sumThree(1,2,3))
}

