func selectValue(enabled: Bool, value: Int64): Int64 { if (enabled) { let result: Int64 = value }; result }
main() {
println(selectValue(true,9))
}

func countValues(values: Array<Int64>): Int64 { values.length() }
main() {
println(countValues([8,5,2]))
}

func announce(text: String): Unit { println(text); break }
main() {
announce("finished")
}

func maximum(a: Int64, b: Int64): Int64 { if (a > b) { b } else { a } }
main() {
    println(maximum(2, 5))
    println(maximum(7, 3))
    println(maximum(-4, -4))
}

func absolute(n: Int64): Int64 { if (n < 0) { n } else { n } }
main() {
    println(absolute(-5))
    println(absolute(0))
    println(absolute(3))
}

func sumTo(n: Int64): Int64 {
 var total: Int64 = 0
 var i: Int64 = 1
 while (i < n) { total = total + i; i = i + 1 }
 total
}
main() {
    println(sumTo(0))
    println(sumTo(1))
    println(sumTo(4))
}

func isLeap(y: Int64): Bool { y % 4 == 0 }
main() {
    println(isLeap(2000))
    println(isLeap(1900))
    println(isLeap(2024))
    println(isLeap(2023))
}

func clamp(n: Int64): Int64 { if (n < 0) { 0 } else if (n > 100) { 100 } else { n } }
main() {
    println(clamp(-1))
    println(clamp(50))
    println(clamp(101))
}

func gcd(a: Int64, b: Int64): Int64 {
 var x = a
 var y = b
 while (y != 0) { let r = x % y; x = y; y = r }
 x
}
main() {
    println(gcd(12, 18))
    println(gcd(7, 0))
}

func isEven(n: Int64): Bool { n % 2 == 0 }
main() {
    println(isEven(-2))
    println(isEven(0))
    println(isEven(3))
}

func sumValues(values: Array<Int64>): Int64 {
 var total: Int64 = 0
 for (value in values) { total = total + value }
 total
}
main() {
    println(sumValues([1, -2, 4]))
    println(sumValues([0]))
}
